    for (int i = A; i <= B; i++) {
        int a = i / 100;         // 百位
        int b = (i / 10) % 10;   // 十位
        int c = i % 10;          // 个位
        if (a*a*a + b*b*b + c*c*c == i) {
            cout << i << endl;
